window.RP_SESSION={"id":"S-818d15c5e827","messages":[{"id":"RP-0221814","time":"2026-08-10T15:25:00+09:00","room":"RP","name":"코블스톤","profile":"스나가와 아이다","identity":"reviewed","type":"dialogue","body":"정의란 무엇인가?","characters":["P-b3929f308454"]},{"id":"RP-0221815","time":"2026-08-10T15:25:00+09:00","room":"RP","name":"코블스톤","profile":"스나가와 아이다","identity":"reviewed","type":"dialogue","body":"그것은 올바른 질서.\n\n인간은 더불어 살아가는 존재이므로, 옳고 그름을 가르는 기준이라 부를 수 있을 것이다.","characters":["P-b3929f308454"]},{"id":"RP-0221816","time":"2026-08-10T15:26:00+09:00","room":"RP","name":"코블스톤","profile":"스나가와 아이다","identity":"reviewed","type":"dialogue","body":"정의는 더불어 살아가기를 희구한다. \n\n나는 그러지 못했던 듯 싶다.","characters":["P-b3929f308454"]},{"id":"RP-0221817","time":"2026-08-10T15:26:00+09:00","room":"RP","name":"코블스톤","profile":"스나가와 아이다","identity":"reviewed","type":"dialogue","body":"죄란, 사람의 마음에서 우러난 악의가 자신만을 향해 굽어진 것...\n\n이기적인 행동의 다른 이름.","characters":["P-b3929f308454"]},{"id":"RP-0221818","time":"2026-08-10T15:27:00+09:00","room":"RP","name":"코블스톤","profile":"스나가와 아이다","identity":"reviewed","type":"dialogue","body":"나는, 다만 라운데라께서 말씀하신 정의란 선을 알고도 죄를 짓는 것이라 이해했었다.","characters":["P-b3929f308454"]},{"id":"RP-0221819","time":"2026-08-10T15:27:00+09:00","room":"RP","name":"코블스톤","profile":"스나가와 아이다","identity":"reviewed","type":"dialogue","body":"그래서 이따금 라운데라께서는 기적을 일으켜 천벌을 내리시는 것이다. 고.","characters":["P-b3929f308454"]},{"id":"RP-0221820","time":"2026-08-10T15:27:00+09:00","room":"RP","name":"코블스톤","profile":"스나가와 아이다","identity":"reviewed","type":"dialogue","body":"나도 그런 것을 원했다. 그름을 알고도 죄를 짓는 자들을 향한 심판. \n\n그것은 무력으로도 이룰 수 있으며, 오히려 그것이 가장 정직한 방식이라 생각했다.","characters":["P-b3929f308454"]},{"id":"RP-0221821","time":"2026-08-10T15:27:00+09:00","room":"RP","name":"코블스톤","profile":"스나가와 아이다","identity":"reviewed","type":"dialogue","body":"부러웠다. 열등한 나는 그것을 모방해 내 손에 넣고 싶었다.\n\n천궁. 지키는 무력이자, 죄를 사람으로부터 격리시키는 빛을.","characters":["P-b3929f308454"]},{"id":"RP-0221822","time":"2026-08-10T15:28:00+09:00","room":"RP","name":"코블스톤","profile":"스나가와 아이다","identity":"reviewed","type":"dialogue","body":"그러고는, '신성력의 부재'에 대해선 '괜찮다'로 일관했다.\n\n그런 쩨쩨한 것쯤은 아무래도 좋다며. 정작 그것이 어째서 부재하는지조차 알려 하지 않으면서.","characters":["P-b3929f308454"]},{"id":"RP-0221823","time":"2026-08-10T15:28:00+09:00","room":"RP","name":"코블스톤","profile":"스나가와 아이다","identity":"reviewed","type":"dialogue","body":"그 결과, 오늘에 이르렀다.\n\n어쩌면, 아니. 확실히 나는 오만했고. 이기적이었다.","characters":["P-b3929f308454"]},{"id":"RP-0221824","time":"2026-08-10T15:28:00+09:00","room":"RP","name":"코블스톤","profile":"스나가와 아이다","identity":"reviewed","type":"dialogue","body":"죄를 지었다.\n\n기억의 공백과 스스로의 무능함을, 특이함과 허세로 덧칠하고 싶었던 것이다.","characters":["P-b3929f308454"]},{"id":"RP-0221825","time":"2026-08-10T15:29:00+09:00","room":"RP","name":"코블스톤","profile":"스나가와 아이다","identity":"reviewed","type":"dialogue","body":"그것이—마공학 의수와 잡다한 장난감 발명품들을 제외하면—내가 오직 무장만을 마공학으로 지어온 이유였다.","characters":["P-b3929f308454"]},{"id":"RP-0221826","time":"2026-08-10T15:29:00+09:00","room":"RP","name":"코블스톤","profile":"스나가와 아이다","identity":"reviewed","type":"dialogue","body":"이제는, 그 사실을 인정하기로 한다.","characters":["P-b3929f308454"]},{"id":"RP-0221827","time":"2026-08-10T15:29:00+09:00","room":"RP","name":"코블스톤","profile":"스나가와 아이다","identity":"reviewed","type":"dialogue","body":"이내 천궁을 들고 길드 대장간에 들어왔다.\n\n그것에 불을 질러 녹였다.","characters":["P-b3929f308454"]},{"id":"RP-0221828","time":"2026-08-10T15:29:00+09:00","room":"RP","name":"코블스톤","profile":"스나가와 아이다","identity":"reviewed","type":"dialogue","body":"이것 없이 내가 아무것도 아니라면, 더더욱 이 망치를 가져선 안 되는 것이겠지.","characters":["P-b3929f308454"]},{"id":"RP-0221829","time":"2026-08-10T15:29:00+09:00","room":"RP","name":"코블스톤","profile":"스나가와 아이다","identity":"reviewed","type":"dialogue","body":"오늘도 제대로 살아가지 못하는 나니까.","characters":["P-b3929f308454"]},{"id":"RP-0221830","time":"2026-08-10T15:30:00+09:00","room":"RP","name":"코블스톤","profile":"스나가와 아이다","identity":"reviewed","type":"dialogue","body":"더불어, 잃어버린 20년은 아직 묻어두기로 했다.\n\n기억난 과거의 편린은 언젠가 또다시 수면 위로 떠오르겠지.","characters":["P-b3929f308454"]},{"id":"RP-0221831","time":"2026-08-10T15:31:00+09:00","room":"RP","name":"코블스톤","profile":"스나가와 아이다","identity":"reviewed","type":"dialogue","body":"좀 더, 나를 멀쩡한 것으로 채운 이후에 찾아보기로 한다.","characters":["P-b3929f308454"]},{"id":"RP-0221832","time":"2026-08-10T15:31:00+09:00","room":"RP","name":"코블스톤","profile":"스나가와 아이다","identity":"reviewed","type":"dialogue","body":"\" ... \"","characters":["P-b3929f308454"]},{"id":"RP-0221833","time":"2026-08-10T15:31:00+09:00","room":"RP","name":"코블스톤","profile":"스나가와 아이다","identity":"reviewed","type":"dialogue","body":"사진","characters":["P-b3929f308454"]},{"id":"RP-0221834","time":"2026-08-10T15:31:00+09:00","room":"RP","name":"코블스톤","profile":"스나가와 아이다","identity":"reviewed","type":"dialogue","body":"\" 아틔시, 아니, 나는. \"","characters":["P-b3929f308454"]},{"id":"RP-0221835","time":"2026-08-10T15:31:00+09:00","room":"RP","name":"코블스톤","profile":"스나가와 아이다","identity":"reviewed","type":"dialogue","body":"사진","characters":["P-b3929f308454"]},{"id":"RP-0221836","time":"2026-08-10T15:31:00+09:00","room":"RP","name":"코블스톤","profile":"스나가와 아이다","identity":"reviewed","type":"dialogue","body":"사진","characters":["P-b3929f308454"]},{"id":"RP-0221837","time":"2026-08-10T15:31:00+09:00","room":"RP","name":"코블스톤","profile":"스나가와 아이다","identity":"reviewed","type":"dialogue","body":"\" ...역시 방패 쯤으로 시작하는게 좋겠어. \"","characters":["P-b3929f308454"]},{"id":"RP-0221838","time":"2026-08-10T15:32:00+09:00","room":"RP","name":"코블스톤","profile":"스나가와 아이다","identity":"reviewed","type":"dialogue","body":"\" 그리고, 오늘 밤엔 경전을 읽자. \"","characters":["P-b3929f308454"]},{"id":"RP-0221839","time":"2026-08-10T15:33:00+09:00","room":"RP","name":"코블스톤","profile":"스나가와 아이다","identity":"reviewed","type":"dialogue","body":"대장간에 연기가 피어올랐다.","characters":["P-b3929f308454"]},{"id":"RP-0221840","time":"2026-08-10T15:33:00+09:00","room":"RP","name":"코블스톤","profile":"스나가와 아이다","identity":"reviewed","type":"dialogue","body":"-fin","characters":["P-b3929f308454"]},{"id":"RP-0221841","time":"2026-08-10T15:33:00+09:00","room":"RP","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"... 계속.\n메시지가 삭제되었습니다.","characters":[]}]};
